using System; using System.Linq; using Mono.Cecil; class V { static int Main(string[] a) { var asm = AssemblyDefinition.ReadAssembly(a[0]); foreach (var f in a.Skip(1)) { foreach (var t in asm.MainModule.Types.Where(x => x.Name == f)) { foreach (var m in t.Methods.Where(x => x.IsPublic || x.IsFamily)) Console.WriteLine(t.Name + " :: " + m.Name + " virtual=" + m.IsVirtual + " abstract=" + m.IsAbstract); } } return 0; } }
